{
  "name": "get_weather",
  "description": "지정한 도시의 현재 날씨를 조회합니다. 사용자가 날씨, 기온, 비 여부를 물을 때 사용합니다. 도시 이름을 받아 날씨 정보를 문자열로 돌려줍니다.",
  "input_schema": {
    "type": "object",
    "properties": {
      "location": {
        "type": "string",
        "description": "도시 이름. 예: 서울"
      }
    },
    "required": ["location"]
  },
  "input_examples": [
    {"location": "서울"}
  ]
}
